-- Restore Tak-Tak's actual option3 credit -> credit -> Temple transfer chain.
-- Only the duplicate Gossip Select row becomes LINK; native gates/actions stay.
SET @tak_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
SET @tak_smart_scripts=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR),'NULL'),COALESCE(CAST(`source_type` AS CHAR),'NULL'),COALESCE(CAST(`id` AS CHAR),'NULL'),COALESCE(CAST(`link` AS CHAR),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR),'NULL'),COALESCE(CAST(`event_type` AS CHAR),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR),'NULL'),COALESCE(CAST(`event_chance` AS CHAR),'NULL'),COALESCE(CAST(`event_flags` AS CHAR),'NULL'),COALESCE(CAST(`event_param1` AS CHAR),'NULL'),COALESCE(CAST(`event_param2` AS CHAR),'NULL'),COALESCE(CAST(`event_param3` AS CHAR),'NULL'),COALESCE(CAST(`event_param4` AS CHAR),'NULL'),COALESCE(CAST(`event_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_type` AS CHAR),'NULL'),COALESCE(CAST(`action_param1` AS CHAR),'NULL'),COALESCE(CAST(`action_param2` AS CHAR),'NULL'),COALESCE(CAST(`action_param3` AS CHAR),'NULL'),COALESCE(CAST(`action_param4` AS CHAR),'NULL'),COALESCE(CAST(`action_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_param6` AS CHAR),'NULL'),COALESCE(CAST(`target_type` AS CHAR),'NULL'),COALESCE(CAST(`target_param1` AS CHAR),'NULL'),COALESCE(CAST(`target_param2` AS CHAR),'NULL'),COALESCE(CAST(`target_param3` AS CHAR),'NULL'),COALESCE(CAST(`target_param4` AS CHAR),'NULL'),COALESCE(CAST(`target_x` AS CHAR),'NULL'),COALESCE(CAST(`target_y` AS CHAR),'NULL'),COALESCE(CAST(`target_z` AS CHAR),'NULL'),COALESCE(CAST(`target_o` AS CHAR),'NULL'),COALESCE(CAST(`comment` AS CHAR),'NULL')) ORDER BY `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment` SEPARATOR '\n'),256) FROM smart_scripts WHERE entryorguid=101880 AND source_type=0);
SET @tak_conditions=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM conditions WHERE (SourceTypeOrReferenceId=15 AND SourceGroup=19254) OR (SourceTypeOrReferenceId=22 AND SourceEntry=101880));
SET @tak_gossip_menu_option=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`MenuID` AS CHAR),'NULL'),COALESCE(CAST(`OptionID` AS CHAR),'NULL'),COALESCE(CAST(`OptionNpc` AS CHAR),'NULL'),COALESCE(CAST(`OptionText` AS CHAR),'NULL'),COALESCE(CAST(`OptionBroadcastTextID` AS CHAR),'NULL'),COALESCE(CAST(`ActionMenuID` AS CHAR),'NULL'),COALESCE(CAST(`ActionPoiID` AS CHAR),'NULL'),COALESCE(CAST(`BoxCoded` AS CHAR),'NULL'),COALESCE(CAST(`BoxMoney` AS CHAR),'NULL'),COALESCE(CAST(`BoxText` AS CHAR),'NULL'),COALESCE(CAST(`BoxBroadcastTextID` AS CHAR),'NULL'),COALESCE(CAST(`VerifiedBuild` AS CHAR),'NULL')) ORDER BY `MenuID`,`OptionID`,`OptionNpc`,`OptionText`,`OptionBroadcastTextID`,`ActionMenuID`,`ActionPoiID`,`BoxCoded`,`BoxMoney`,`BoxText`,`BoxBroadcastTextID`,`VerifiedBuild` SEPARATOR '\n'),256) FROM gossip_menu_option WHERE MenuID=19254);
SET @tak_creature_template=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entry` AS CHAR),'NULL'),COALESCE(CAST(`gossip_menu_id` AS CHAR),'NULL'),COALESCE(CAST(`minlevel` AS CHAR),'NULL'),COALESCE(CAST(`maxlevel` AS CHAR),'NULL'),COALESCE(CAST(`HealthScalingExpansion` AS CHAR),'NULL'),COALESCE(CAST(`SandboxScalingID` AS CHAR),'NULL'),COALESCE(CAST(`exp` AS CHAR),'NULL'),COALESCE(CAST(`faction` AS CHAR),'NULL'),COALESCE(CAST(`npcflag` AS CHAR),'NULL'),COALESCE(CAST(`npcflag2` AS CHAR),'NULL'),COALESCE(CAST(`speed_walk` AS CHAR),'NULL'),COALESCE(CAST(`speed_run` AS CHAR),'NULL'),COALESCE(CAST(`speed_fly` AS CHAR),'NULL'),COALESCE(CAST(`scale` AS CHAR),'NULL'),COALESCE(CAST(`mindmg` AS CHAR),'NULL'),COALESCE(CAST(`maxdmg` AS CHAR),'NULL'),COALESCE(CAST(`dmgschool` AS CHAR),'NULL'),COALESCE(CAST(`attackpower` AS CHAR),'NULL'),COALESCE(CAST(`dmg_multiplier` AS CHAR),'NULL'),COALESCE(CAST(`baseattacktime` AS CHAR),'NULL'),COALESCE(CAST(`rangeattacktime` AS CHAR),'NULL'),COALESCE(CAST(`unit_class` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags2` AS CHAR),'NULL'),COALESCE(CAST(`unit_flags3` AS CHAR),'NULL'),COALESCE(CAST(`dynamicflags` AS CHAR),'NULL'),COALESCE(CAST(`trainer_type` AS CHAR),'NULL'),COALESCE(CAST(`trainer_spell` AS CHAR),'NULL'),COALESCE(CAST(`trainer_class` AS CHAR),'NULL'),COALESCE(CAST(`trainer_race` AS CHAR),'NULL'),COALESCE(CAST(`minrangedmg` AS CHAR),'NULL'),COALESCE(CAST(`maxrangedmg` AS CHAR),'NULL'),COALESCE(CAST(`rangedattackpower` AS CHAR),'NULL'),COALESCE(CAST(`lootid` AS CHAR),'NULL'),COALESCE(CAST(`pickpocketloot` AS CHAR),'NULL'),COALESCE(CAST(`skinloot` AS CHAR),'NULL'),COALESCE(CAST(`resistance1` AS CHAR),'NULL'),COALESCE(CAST(`resistance2` AS CHAR),'NULL'),COALESCE(CAST(`resistance3` AS CHAR),'NULL'),COALESCE(CAST(`resistance4` AS CHAR),'NULL'),COALESCE(CAST(`resistance5` AS CHAR),'NULL'),COALESCE(CAST(`resistance6` AS CHAR),'NULL'),COALESCE(CAST(`spell1` AS CHAR),'NULL'),COALESCE(CAST(`spell2` AS CHAR),'NULL'),COALESCE(CAST(`spell3` AS CHAR),'NULL'),COALESCE(CAST(`spell4` AS CHAR),'NULL'),COALESCE(CAST(`spell5` AS CHAR),'NULL'),COALESCE(CAST(`spell6` AS CHAR),'NULL'),COALESCE(CAST(`spell7` AS CHAR),'NULL'),COALESCE(CAST(`spell8` AS CHAR),'NULL'),COALESCE(CAST(`PetSpellDataId` AS CHAR),'NULL'),COALESCE(CAST(`VehicleId` AS CHAR),'NULL'),COALESCE(CAST(`mingold` AS CHAR),'NULL'),COALESCE(CAST(`maxgold` AS CHAR),'NULL'),COALESCE(CAST(`AIName` AS CHAR),'NULL'),COALESCE(CAST(`MovementType` AS CHAR),'NULL'),COALESCE(CAST(`HoverHeight` AS CHAR),'NULL'),COALESCE(CAST(`Mana_mod_extra` AS CHAR),'NULL'),COALESCE(CAST(`Armor_mod` AS CHAR),'NULL'),COALESCE(CAST(`RegenHealth` AS CHAR),'NULL'),COALESCE(CAST(`mechanic_immune_mask` AS CHAR),'NULL'),COALESCE(CAST(`flags_extra` AS CHAR),'NULL'),COALESCE(CAST(`ControllerID` AS CHAR),'NULL'),COALESCE(CAST(`WorldEffects` AS CHAR),'NULL'),COALESCE(CAST(`PassiveSpells` AS CHAR),'NULL'),COALESCE(CAST(`StateWorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimKitID` AS CHAR),'NULL'),COALESCE(CAST(`IgnoreLos` AS CHAR),'NULL'),COALESCE(CAST(`AffixState` AS CHAR),'NULL'),COALESCE(CAST(`MaxVisible` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL')) ORDER BY `entry`,`gossip_menu_id`,`minlevel`,`maxlevel`,`HealthScalingExpansion`,`SandboxScalingID`,`exp`,`faction`,`npcflag`,`npcflag2`,`speed_walk`,`speed_run`,`speed_fly`,`scale`,`mindmg`,`maxdmg`,`dmgschool`,`attackpower`,`dmg_multiplier`,`baseattacktime`,`rangeattacktime`,`unit_class`,`unit_flags`,`unit_flags2`,`unit_flags3`,`dynamicflags`,`trainer_type`,`trainer_spell`,`trainer_class`,`trainer_race`,`minrangedmg`,`maxrangedmg`,`rangedattackpower`,`lootid`,`pickpocketloot`,`skinloot`,`resistance1`,`resistance2`,`resistance3`,`resistance4`,`resistance5`,`resistance6`,`spell1`,`spell2`,`spell3`,`spell4`,`spell5`,`spell6`,`spell7`,`spell8`,`PetSpellDataId`,`VehicleId`,`mingold`,`maxgold`,`AIName`,`MovementType`,`HoverHeight`,`Mana_mod_extra`,`Armor_mod`,`RegenHealth`,`mechanic_immune_mask`,`flags_extra`,`ControllerID`,`WorldEffects`,`PassiveSpells`,`StateWorldEffectID`,`SpellStateVisualID`,`SpellStateAnimID`,`SpellStateAnimKitID`,`IgnoreLos`,`AffixState`,`MaxVisible`,`ScriptName` SEPARATOR '\n'),256) FROM creature_template WHERE entry=101880);
SET @tak_old=@tak_smart_scripts='01913cbba2eb1c68b26c7dd47b9860932954318433ef0a380657e96702ed697d';
SET @tak_applied=@tak_smart_scripts='2541dd41fc4db223cd2abcfd5a01647f018753abf3dcdc24a92d76b76fb1f744';
SET @tak_safe=(@tak_old OR @tak_applied) AND @tak_conditions='750ee736cd7fb49fb95219ec5cf445dc5b2db409a0ae12b0f94d5429f3da05c6' AND @tak_gossip_menu_option='7e6c4dbfe81b447e1a29fc6a7a08889aa7aabda6159f9ffb084b11daa1a6acb4' AND @tak_creature_template='70043282e9e16e1ef353cba84624281d241eea5d957bb22bf82203494b2e9f14';
SET @tak_guard=IF(COALESCE(@tak_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Tak-Tak graph/menu/conditions/actor differ; review before updating''');
PREPARE tak_guard FROM @tak_guard;EXECUTE tak_guard;DEALLOCATE PREPARE tak_guard;
UPDATE smart_scripts SET event_type=61,event_param1=0,event_param2=0,comment='Link - Kill Credit'
WHERE @tak_safe AND @tak_old AND entryorguid=101880 AND source_type=0 AND id=6;
COMMIT;
SET SESSION group_concat_max_len=@tak_concat;
